try { task_id = $('Validate Specs').first().json.task_id || "unknown"; } catch(e) {}

const injectData = $('Inject Prompt').first().json;
const mode = injectData.mode || 'deterministic';
let serverJs = injectData._server_js || injectData.base_server_js || '';

if (mode === 'llm_improve') {
  // Parser la réponse LLM
  try {
