// Récupérer stores et data_model depuis Inject Prompt pour les propager
const _inj = injectData; // déjà lu : $('Inject Prompt').first().json
const _stores    = _inj.stores    || {};
const _dataModel = _inj.data_model || {};
const _endpoints = _inj.priority_endpoints || _inj.endpoints || [];

// Fichiers SQLite additionnels
const _dbJs      = injectData._db_js      || '';
const _schemaSql = injectData._schema_sql || '';

const _files = [
  { path: 'server.js',    content: '// FILE: server.js\n' + serverJs },
  { path: 'package.json', content: '// FILE: package.json\n' + packageJson },
  { path: '.env.example', content: '// FILE: .env.example\nPORT=3000\nDB_PATH=./database.db\nNODE_ENV=development\n' }
];
if (_dbJs.length > 10)      _files.push({ path: 'db.js',      content: '// FILE: db.js\n'      + _dbJs });
if (_schemaSql.length > 10) _files.push({ path: 'schema.sql', content: '-- FILE: schema.sql\n' + _schemaSql });

return [{ json: {
  agent: "developer", task_id,
  files: _files,
  errors: [],
  stores:             _stores,
  data_model:         _dataModel,
  priority_endpoints: _endpoints
}}];

console.log("🟢 BACKEND V5.8 — SQLite + better-sqlite3");
var items = $input.all();
if (!items || items.length === 0) throw new Error("Aucune donnée reçue");
var inputData = items[0].json;

var arch         = inputData.architecture || {};
var endpoints    = inputData.priority_endpoints || arch.priority_endpoints || [];
var dataModel    = inputData.data_model   || arch.data_model   || {};
var stores       = inputData.stores       || arch.stores       || {};
var manifest     = arch.file_manifest     || [];
var improveMode  = inputData.improve_mode || false;
var hasFrontend  = manifest.some(function(f){ return f.includes('frontend'); });
if (improveMode && !hasFrontend) { hasFrontend = true; }
var backendInstructions = inputData.backend_instructions || [];
var improvePrompt = inputData.userRequest || '';
var existingServerJs = inputData.existing_server_js || '';
var existingRoutes   = inputData.existing_routes    || [];
var existingStores   = inputData.existing_stores    || {};

// ── Construire la config ressources ───────────────────────────────────────
function getResourceConfig(path) {
  if (!path || path === '/health') return null;
  var seg = path.replace(/^\//, '').split('/')[0];
  for (var res in stores) {
    if (stores[res].store_name === seg) {
      return { resName: res, storeName: seg, requiredFields: stores[res].required_fields || [], fields: dataModel[res] || {} };
    }
  }
  var resName = seg.replace(/s$/, '');
  var fields  = dataModel[resName] || {};
  var required = Object.keys(fields).filter(function(k){ return !['id','created_at','updated_at','status'].includes(k); });
  return { resName: resName, storeName: seg, requiredFields: required, fields: fields };
}

// ── GARDE-FOU MODE AMÉLIORATION ───────────────────────────────────────────
if (improveMode && endpoints.length === 0 && existingRoutes.length > 0) {
  existingRoutes.forEach(function(r) {
    if (r.method && r.path) endpoints.push({ method: r.method, path: r.path, description: 'route conservée' });
  });
  if (Object.keys(existingStores).length > 0) {
    Object.keys(existingStores).forEach(function(rk) { if (!stores[rk]) stores[rk] = existingStores[rk]; });
  }
}

// ── Ajouter DELETE automatiquement ────────────────────────────────────────
var epPaths = endpoints.map(function(ep){ return ep.method + ep.path; });
endpoints.slice().forEach(function(ep) {
  if (ep.method === 'GET' && ep.path !== '/health' && !ep.path.includes(':')) {
    var delPath = ep.path + '/:id';
    if (!epPaths.includes('DELETE' + delPath)) {
      endpoints.push({ method: 'DELETE', path: delPath, description: 'supprimer par id' });
    }
  }
});

var storeNames = [];
endpoints.forEach(function(ep) {
  var cfg = getResourceConfig(ep.path);
  if (cfg && storeNames.indexOf(cfg.storeName) === -1) storeNames.push(cfg.storeName);
});

var resourceConfig = {};
storeNames.forEach(function(sn) {
  endpoints.forEach(function(ep) {
    var cfg = getResourceConfig(ep.path);
    if (cfg && cfg.storeName === sn && !resourceConfig[sn]) resourceConfig[sn] = cfg;
  });
});

// ── SQL TYPE MAPPING ──────────────────────────────────────────────────────
function sqlType(fieldName, fieldType) {
  if (['id'].includes(fieldName)) return 'INTEGER PRIMARY KEY AUTOINCREMENT';
  if (fieldName === 'created_at') return "TEXT DEFAULT (datetime('now'))";
  if (fieldType !== 'number') return 'TEXT';
  var fLow = fieldName.toLowerCase();
  if (fLow.endsWith('_id')) return 'INTEGER';
  if (['latitude','longitude','prix','montant','poids','kilos','note','score'].some(function(k){ return fLow.includes(k); })) return 'REAL';
  return 'INTEGER';
}

function sqlTable(sn) {
  var cfg = resourceConfig[sn];
  if (!cfg) return '';
  var allFields = Object.assign({ id: 'number', created_at: 'string' }, cfg.fields);
  var lines = ['CREATE TABLE IF NOT EXISTS ' + sn + ' ('];
  var colDefs = [];
  colDefs.push('  id INTEGER PRIMARY KEY AUTOINCREMENT');
  Object.keys(cfg.fields).filter(function(k){ return k !== 'id' && k !== 'created_at'; }).forEach(function(k) {
    var sType = sqlType(k, cfg.fields[k]);
    var notNull = cfg.requiredFields.includes(k) ? ' NOT NULL' : '';
    // FK reference
    var fkRef = '';
    if (k.endsWith('_id') && sType === 'INTEGER') {
      var refBase = k.replace(/_id$/, '');
      var refTable = refBase + 's';
      if (storeNames.includes(refTable)) fkRef = ' REFERENCES ' + refTable + '(id)';
      else if (storeNames.includes(refBase)) fkRef = ' REFERENCES ' + refBase + '(id)';
    }
    colDefs.push('  ' + k + ' ' + sType + notNull + fkRef);
  });
  colDefs.push("  created_at TEXT DEFAULT (datetime('now'))");
  lines.push(colDefs.join(',\n'));
  lines.push(');');
  return lines.join('\n');
}

// ── GÉNÉRER schema.sql ────────────────────────────────────────────────────
var schemaSql = '-- schema.sql — généré par Forge IA Backend V5.8\n-- Tables SQLite avec types TEXT / INTEGER / REAL\n\n';
storeNames.forEach(function(sn) { schemaSql += sqlTable(sn) + '\n\n'; });

// ── GÉNÉRER db.js ─────────────────────────────────────────────────────────
var dbJs = [
  "const Database = require('better-sqlite3');",
  "const path = require('path');",
  "const fs   = require('fs');",
  "",
  "const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'database.db');",
  "const db = new Database(DB_PATH);",
  "",
  "// Activer WAL (performances) + clés étrangères",
  "db.pragma('journal_mode = WAL');",
  "db.pragma('foreign_keys = ON');",
  "",
  "// Exécuter le schéma au démarrage (idempotent — CREATE TABLE IF NOT EXISTS)",
  "const schemaPath = path.join(__dirname, 'schema.sql');",
  "if (fs.existsSync(schemaPath)) {",
  "  const schema = fs.readFileSync(schemaPath, 'utf8');",
  "  db.exec(schema);",
  "}",
  "",
  "module.exports = db;"
].join('\n');

// ── GÉNÉRER server.js (SQLite) ────────────────────────────────────────────
var L = [];
L.push("const express = require('express');");
if (hasFrontend) L.push("const path = require('path');");
L.push("require('dotenv').config();");
L.push("const db  = require('./db');");
L.push("const app = express();");
L.push("const PORT = process.env.PORT || 3000;");
L.push("app.use(express.json({ limit: '50kb' }));");
if (hasFrontend) L.push("app.use(express.static(path.join(__dirname, 'frontend')));");
L.push("");

endpoints.forEach(function(ep) {
  var m   = ep.method.toLowerCase();
  var r   = ep.path;
  var seg = r.replace(/^\//, '').split('/')[0];
  var cfg = resourceConfig[seg] || {};
  var sn  = cfg.storeName || seg;
  var req = cfg.requiredFields || [];
  var allFields = Object.keys(cfg.fields || {}).filter(function(k){ return !['id','created_at'].includes(k); });
  var desc = ep.description || '';

  L.push('// ' + ep.method + ' ' + r + ' — ' + desc);

  if (r === '/health') {
    L.push("app.get('/health', (req, res) => {");
    L.push("  res.json({ status: 'OK', uptime: process.uptime() });");
    L.push("});");

  } else if (m === 'get' && !r.includes(':')) {
    L.push("app.get('" + r + "', (req, res) => {");
    L.push("  try {");
    L.push("    const items = db.prepare('SELECT * FROM " + sn + " ORDER BY id ASC').all();");
    L.push("    res.json(items);");
    L.push("  } catch(err) { console.error('[' + req.method + ' ' + req.path + ']', err.message); res.status(500).json({ message: 'Erreur interne' }); }");
    L.push("});");

  } else if (m === 'get' && r.includes(':')) {
    L.push("app.get('" + r + "', (req, res) => {");
    L.push("  try {");
    L.push("    const id = parseInt(req.params.id);");
    L.push("    const item = db.prepare('SELECT * FROM " + sn + " WHERE id = ?').get(id);");
    L.push("    if (!item) return res.status(404).json({ message: 'Introuvable' });");
    L.push("    res.json(item);");
    L.push("  } catch(err) { console.error('[' + req.method + ' ' + req.path + ']', err.message); res.status(500).json({ message: 'Erreur interne' }); }");
    L.push("});");

  } else if (m === 'post') {
    var destruct = req.length ? '{ ' + req.join(', ') + ' }' : '{}';
    var checks   = req.map(function(f){ return '!' + f + ' && ' + f + ' !== 0'; }).join(' || ');
    L.push("app.post('" + r + "', (req, res) => {");
    L.push("  try {");
    if (req.length) {
      L.push("    const " + destruct + " = req.body;");
      L.push("    if (" + checks + ") {");
      L.push("      return res.status(400).json({ message: 'Champs requis: " + req.join(', ') + "' });");
      L.push("    }");
      // Validations format
      req.forEach(function(f) {
        var ft = (cfg.fields || {})[f];
        var fl = f.toLowerCase();
        if (ft === 'number') {
          if (fl === 'latitude') {
            L.push("    const _vLat = Number(latitude);");
            L.push("    if (isNaN(_vLat) || _vLat < -90 || _vLat > 90) return res.status(400).json({ message: 'latitude doit être entre -90 et 90' });");
          } else if (fl === 'longitude') {
            L.push("    const _vLng = Number(longitude);");
            L.push("    if (isNaN(_vLng) || _vLng < -180 || _vLng > 180) return res.status(400).json({ message: 'longitude doit être entre -180 et 180' });");
          } else if (fl.endsWith('_id')) {
            var refBase = fl.replace(/_id$/, '');
            var refTbl  = storeNames.includes(refBase + 's') ? refBase + 's' : (storeNames.includes(refBase) ? refBase : null);
            L.push("    const _v" + f.charAt(0).toUpperCase() + f.slice(1) + " = Number(" + f + ");");
            L.push("    if (isNaN(_v" + f.charAt(0).toUpperCase() + f.slice(1) + ") || _v" + f.charAt(0).toUpperCase() + f.slice(1) + " <= 0) return res.status(400).json({ message: '" + f + " doit être un identifiant valide' });");
            if (refTbl) {
              L.push("    if (!db.prepare('SELECT id FROM " + refTbl + " WHERE id = ?').get(_v" + f.charAt(0).toUpperCase() + f.slice(1) + ")) return res.status(404).json({ message: '" + f + " : référence introuvable' });");
            }
          } else {
            L.push("    if (isNaN(Number(" + f + ")) || Number(" + f + ") <= 0) return res.status(400).json({ message: '" + f + " doit être un nombre positif' });");
          }
        } else if (fl === 'description' || fl === 'libelle') {
          L.push("    if (String(" + f + " || '').trim().length < 5) return res.status(400).json({ message: '" + f + " doit contenir au moins 5 caractères' });");
        }
      });
    }
    // INSERT SQL paramétré
    var insertCols = req.join(', ');
    var insertVals = req.map(function(f){
      var ft = (cfg.fields || {})[f];
      if (ft === 'number') return "Number(" + f + ")";
      return f;
    }).join(', ');
    var placeholders = req.map(function(){ return '?'; }).join(', ');
    L.push("    const stmt = db.prepare('INSERT INTO " + sn + " (" + insertCols + ") VALUES (" + placeholders + ")');");
    L.push("    const result = stmt.run(" + insertVals + ");");
    L.push("    const item = db.prepare('SELECT * FROM " + sn + " WHERE id = ?').get(result.lastInsertRowid);");
    L.push("    res.status(201).json(item);");
    L.push("  } catch(err) { console.error('[' + req.method + ' ' + req.path + ']', err.message); res.status(500).json({ message: 'Erreur interne' }); }");
    L.push("});");

  } else if (m === 'delete') {
    L.push("app.delete('" + r + "', (req, res) => {");
    L.push("  try {");
    L.push("    const id = parseInt(req.params.id);");
    L.push("    const item = db.prepare('SELECT id FROM " + sn + " WHERE id = ?').get(id);");
    L.push("    if (!item) return res.status(404).json({ message: 'Introuvable' });");
    L.push("    db.prepare('DELETE FROM " + sn + " WHERE id = ?').run(id);");
    L.push("    res.json({ message: 'Supprimé' });");
    L.push("  } catch(err) { console.error('[' + req.method + ' ' + req.path + ']', err.message); res.status(500).json({ message: 'Erreur interne' }); }");
    L.push("});");

  } else if (m === 'put' || m === 'patch') {
    var updFields = req.length ? req : allFields;
    var setClauses = updFields.map(function(f){ return f + ' = ?'; }).join(', ');
    var setVals    = updFields.map(function(f){
      var ft = (cfg.fields || {})[f];
      return ft === 'number' ? "Number(req.body." + f + ")" : "req.body." + f;
    }).join(', ');
    L.push("app." + m + "('" + r + "', (req, res) => {");
    L.push("  try {");
    L.push("    const id = parseInt(req.params.id);");
    L.push("    const existing = db.prepare('SELECT id FROM " + sn + " WHERE id = ?').get(id);");
    L.push("    if (!existing) return res.status(404).json({ message: 'Introuvable' });");
    L.push("    db.prepare('UPDATE " + sn + " SET " + setClauses + " WHERE id = ?').run(" + setVals + ", id);");
    L.push("    const item = db.prepare('SELECT * FROM " + sn + " WHERE id = ?').get(id);");
    L.push("    res.json(item);");
    L.push("  } catch(err) { console.error('[' + req.method + ' ' + req.path + ']', err.message); res.status(500).json({ message: 'Erreur interne' }); }");
    L.push("});");
  }
  L.push("");
});

L.push("app.listen(PORT, () => console.log('✅ Serveur sur port ' + PORT));");
var baseServerJs = L.join('\n');

// ── Package.json avec better-sqlite3 ─────────────────────────────────────
var pkgJson = JSON.stringify({
  name: (storeNames[0] || 'api') + '-api',
  version: '1.0.0',
  main: 'server.js',
  scripts: { start: 'node server.js' },
  dependencies: {
    'express':        '^4.18.2',
    'dotenv':         '^16.0.0',
    'better-sqlite3': '^9.4.3'
  }
}, null, 2);

// ── MODE AMÉLIORATION ─────────────────────────────────────────────────────
if (improveMode && improvePrompt) {
  var systemPrompt = 'Tu es un développeur backend Node.js/Express+SQLite senior.\n\n' +
    'TACHE : Améliorer le code server.js fourni selon le prompt.\n' +
    'CONSERVER toutes les routes et requêtes SQL existantes.\n' +
    'AJOUTER les améliorations demandées.\n\n' +
    'RÈGLE ABSOLUE : Retourner UNIQUEMENT un JSON valide.\n' +
    'FORMAT : { "agent": "developer", "server_js": "// code amélioré" }\n\n' +
    'RÈGLES :\n' +
    '1. Utiliser uniquement des requêtes SQL paramétrées (jamais de concaténation)\n' +
    '2. Conserver db.pragma, foreign_keys, WAL\n' +
    '3. Code syntaxiquement valide\n';
  var instrBlock = backendInstructions.length > 0 ? '\nINSTRUCTIONS :\n' + backendInstructions.join('\n') + '\n\n' : '';
  var userPrompt = 'PROMPT :\n' + improvePrompt + '\n\n' + instrBlock +
    'CODE SERVER.JS BASE :\n```javascript\n' + baseServerJs + '\n```\n\n' +
    'Retourne UNIQUEMENT le JSON avec le server.js amélioré.';

  return [{ json: {
    mode: 'llm_improve',
    systemPrompt, userPrompt,
    base_server_js: baseServerJs,
    endpoints, storeNames, hasFrontend, data_model: dataModel, stores,
    _db_js:      dbJs,
    _schema_sql: schemaSql
  }}];
}

// ── MODE NORMAL ───────────────────────────────────────────────────────────
return [{ json: {
  mode: 'deterministic',
  _deterministic: true,
  _server_js:   baseServerJs,
  _db_js:       dbJs,
  _schema_sql:  schemaSql,
  stores, data_model: dataModel, storeNames, priority_endpoints: endpoints,
  _package_json: pkgJson,
  choices: [{ message: { content: JSON.stringify({
    agent: 'developer',
    logic: { server: baseServerJs, db: dbJs, schema: schemaSql },
    errors: []
  }) } }]
}}];

const input = $input.first().json;

let files = input.files || [];
const errors = input.errors || [];

// Conversion si files est un objet numéroté
if (!Array.isArray(files) && typeof files === 'object') {
  const filesArray = [];
  for (const key in files) {
    if (files.hasOwnProperty(key) && !isNaN(key)) {
      filesArray.push(files[key]);
    }
  }
  files = filesArray;
}

return [{
  json: {
    agent: input.agent || "developer",
    task_id: input.task_id || "unknown",
    files: files,
    errors: errors,
    stores:             input.stores             || {},
    data_model:         input.data_model         || {},
    priority_endpoints: input.priority_endpoints || [],
    artifacts: input.artifacts || {
      stack: {
        language: "Node.js",
        framework: "Express",
        database: "MongoDB"
      },
      file_count: files.length,
      generation_method: "groq"
    }
  }
}];

const inp = $input.first().json;

// Mode amélioration avec LLM
if (inp.mode === 'llm_improve') {
  return [{
    json: {
      model: "llama-3.3-70b-versatile",
      messages: [
        { role: "system", content: inp.systemPrompt },
        { role: "user",   content: inp.userPrompt }
      ],
      temperature: 0,
      max_tokens: 6000,
      response_format: { type: "json_object" }
    }
  }];
}

// Mode déterministe — pass-through
return [{ json: inp }];

const input = $input.first().json;

const files = input.files || input.data?.specs?.files || [];
const errors = input.errors || input.data?.specs?.errors || [];
const hasFiles = Array.isArray(files) && files.length > 0;
const hasErrors = Array.isArray(errors) && errors.length > 0;

const status = hasFiles && !hasErrors ? "PASS" : "FAIL";

// stores et data_model propagés directement depuis Parse Files → Format response
// Lecture depuis $input (flux direct) — plus fiable que cross-node reference
const _stores    = input.stores             || {};
const _dataModel = input.data_model         || {};
const _endpoints = input.priority_endpoints || [];

return [{
  json: {
    agent: "Agent BACKEND",
    task_id: input.task_id || input.data?.meta?.request_id || "unknown",
    status,
    global_score: hasFiles ? 100 : 0,
    approved_for_pipeline: status === "PASS",
    language: "javascript",
    critical_issues: hasErrors
      ? errors.map(e => ({ severity: "high", description: String(e) }))
      : [],
    warnings: [],
    recommendations: hasFiles
      ? ["Code backend généré avec succès"]
      : ["Régénérer — aucun fichier produit"],
    summary: hasFiles
      ? `${files.length} fichier(s) backend généré(s)`
      : "Échec de génération backend",
    dimensions: {
      security: { score: 100 },
      quality: { score: hasFiles ? 100 : 0 }
    },
    timestamp: new Date().toISOString(),
    files,
    artifacts: input.artifacts || input.data?.specs?.artifacts || {},
    // Passer stores et data_model pour Build Frontend Payload
    stores:             _stores,
    data_model:         _dataModel,
    priority_endpoints: _endpoints
  }
}];
